    commission_amount bigint DEFAULT 0 NOT NULL,
    escrow_amount bigint DEFAULT 0 NOT NULL,
    refunded_amount bigint DEFAULT 0 NOT NULL,
    shipping_option_name text DEFAULT ''::text NOT NULL,
    shipping_transport_type text DEFAULT ''::text NOT NULL,
    auto_release_at timestamp with time zone,
    created_at timestamp with time zone NOT NULL,
    updated_at timestamp with time zone NOT NULL,
