);

CREATE TABLE orders (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    buyer_id uuid NOT NULL,
    seller_id uuid NOT NULL,
    source_type order_source_enum NOT NULL,
    source_id uuid NOT NULL,
    negotiation_id uuid,
    quantity integer NOT NULL,
    unit_price bigint NOT NULL,
    subtotal bigint NOT NULL,
    shipping_total bigint NOT NULL,
    commission_percent integer NOT NULL,
    commission_amount bigint NOT NULL,
    -- DEAD COLUMN (retained for schema compatibility; NEVER a financial
    -- authority): orders.escrow_amount is not written or read by production.
    -- The canonical buyer base / escrow amount is total_before_coins_amount
    -- ((P−D)+S) and the escrows table row. Do NOT revive.
    escrow_amount bigint DEFAULT 0 NOT NULL,
    refunded_amount bigint DEFAULT 0 NOT NULL,
    discount_code text,
    discount_type discount_type_enum,
    discount_value numeric,
    -- DEAD COLUMN (retained for schema compatibility; NEVER a financial
    -- authority): orders.discount_amount is not written or read by production.
    -- Discount is authoritative in the pricing token snapshot. Do NOT revive.
    discount_amount bigint DEFAULT 0 NOT NULL,
    shipping_option_id uuid,
    shipping_option_name text,
    shipping_transport_type text,
    shipping_expedition_name text,
    shipping_estimated_days text,
    shipping_quote_id uuid,
    shipping_quote_price bigint,
    destination_address jsonb,
    preparation_time_snapshot preparation_time_enum,
    ready_to_ship_by timestamp with time zone,
    status order_status_enum NOT NULL,
    escrow_status escrow_status_enum DEFAULT 'none'::escrow_status_enum NOT NULL,
    has_dispute boolean DEFAULT false NOT NULL,
    auto_release_at timestamp with time zone,
    completed_at timestamp with time zone,
    payment_expires_at timestamp with time zone,
    order_number text,
    coins_refunded_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pricing_token_id uuid,
    confirmation_extension_used boolean DEFAULT false NOT NULL,
    confirmation_extended_at timestamp with time zone,
    idempotency_key text,
    preparation_note_snapshot text,
    address_snapshot jsonb,
    tracking_number text,
    proof_type text,
    shipping_proof_media text,
    shipping_note text,
    shipping_destination jsonb,
    shipping_source text,
    shipping_origin_snapshot jsonb,
    service_fee_amount bigint DEFAULT 0 NOT NULL,
    total_payable_amount bigint DEFAULT 0 NOT NULL,
    -- DEAD COLUMNS (retained for schema compatibility; NEVER financial
    -- authorities): orders.coins_used / orders.coin_discount_amount are never
    -- read by production (production no longer writes them). K is
    -- authoritative in the coins domain (user_coin_balance, coin_reservations,
    -- coins_transactions). Do NOT revive.
    coins_used bigint DEFAULT 0 NOT NULL,
    coin_discount_amount bigint DEFAULT 0 NOT NULL,
    total_before_coins_amount bigint DEFAULT 0 NOT NULL
);

