    ticket_id uuid NOT NULL,
    event_type text NOT NULL,
    actor_id uuid,
    old_status ticket_status_enum,
    new_status ticket_status_enum,
    notes text,
    metadata jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE support_tickets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    chat_room_id uuid NOT NULL,
    category ticket_category_enum NOT NULL,
    priority ticket_priority_enum DEFAULT 'medium'::ticket_priority_enum NOT NULL,
    status ticket_status_enum DEFAULT 'open'::ticket_status_enum NOT NULL,
    escalation ticket_escalation_enum DEFAULT 'none'::ticket_escalation_enum NOT NULL,
    linked_order_id uuid,
    assigned_admin_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    assigned_at timestamp with time zone,
    resolved_at timestamp with time zone,
    closed_at timestamp with time zone,
    resolution_notes text,
    close_reason text,
    metadata jsonb
);

CREATE TABLE system_alerts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    alert_type text NOT NULL,
    severity text NOT NULL,
    entity_type text NOT NULL,
    entity_id uuid NOT NULL,
    message text NOT NULL,
    metadata_json jsonb DEFAULT '{}'::jsonb NOT NULL,
    status text DEFAULT 'active'::text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    resolved_at timestamp with time zone,
    resolved_by uuid,
    group_key text,
    dedup_key text DEFAULT ''::text NOT NULL,
    dedup_window integer
);

CREATE TABLE ticket_escalations (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    ticket_id uuid NOT NULL,
    escalated_by uuid NOT NULL,
    from_level ticket_escalation_enum NOT NULL,
    to_level ticket_escalation_enum NOT NULL,
    reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE user_blocks (
    blocker_id uuid NOT NULL,
    blocked_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE user_capabilities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    capability text NOT NULL,
    resource_id uuid,
    granted_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone,
    granted_by uuid,
    revoked_at timestamp with time zone
);

CREATE TABLE user_coin_balance (
    user_id uuid NOT NULL,
    balance bigint DEFAULT 0 NOT NULL,
    version bigint DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE user_follows (
    follower_id uuid NOT NULL,
    following_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE user_mutes (
    muter_id uuid NOT NULL,
    muted_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE user_online_status (
    user_id uuid NOT NULL,
    is_online boolean DEFAULT false NOT NULL,
    last_seen_at timestamp with time zone DEFAULT now() NOT NULL,
    current_room_id uuid
);

CREATE TABLE user_profiles (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    username text,
    bio text,
    avatar_url text,
    date_of_birth date,
    gender text,
    location text,
    city text,
    province text,
    preferred_lang text,
    last_active_at timestamp with time zone,
    followers_count integer DEFAULT 0 NOT NULL,
    following_count integer DEFAULT 0 NOT NULL,
    is_verified boolean DEFAULT false NOT NULL,
    social_media jsonb,
    privacy jsonb,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE user_warnings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    issued_by uuid NOT NULL,
    level text NOT NULL,
    reason text NOT NULL,
    is_active boolean DEFAULT true NOT NULL,
    revoked_at timestamp with time zone,
    revoked_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    expires_at timestamp with time zone
);

CREATE TABLE users (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    firebase_uid text NOT NULL,
    email text NOT NULL,
    phone_number text,
    phone_verified boolean DEFAULT false NOT NULL,
    account_status user_account_status_enum DEFAULT 'active'::user_account_status_enum NOT NULL,
    is_id_verified boolean DEFAULT false NOT NULL,
    is_farm_verified boolean DEFAULT false NOT NULL,
    email_verified_at timestamp with time zone,
    phone_verified_at timestamp with time zone,
    id_verified_at timestamp with time zone,
    farm_verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    deleted_at timestamp with time zone,
    role text DEFAULT 'user'::text NOT NULL
);

CREATE TABLE verification_documents (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    document_type document_type_enum NOT NULL,
    document_name text NOT NULL,
    status document_review_status_enum DEFAULT 'pending'::document_review_status_enum NOT NULL,
    rejection_note text,
    submitted_at timestamp with time zone DEFAULT now() NOT NULL,
    reviewed_at timestamp with time zone,
    reviewed_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    storage_key text
);

CREATE TABLE wallets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    available_balance bigint DEFAULT 0 NOT NULL,
    held_balance bigint DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    pending_withdrawal bigint DEFAULT 0 NOT NULL
);

CREATE TABLE withdrawals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    amount bigint NOT NULL,
    status withdrawal_status_enum DEFAULT 'REQUESTED'::withdrawal_status_enum NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    seller_id uuid,
    idempotency_key text DEFAULT ''::text NOT NULL,
    bank_name_snapshot text DEFAULT ''::text NOT NULL,
    bank_code_snapshot text DEFAULT ''::text NOT NULL,
    account_number_snapshot text DEFAULT ''::text NOT NULL,
    account_holder_snapshot text DEFAULT ''::text NOT NULL,
    external_reference_id text DEFAULT ''::text NOT NULL,
    gateway_response text DEFAULT ''::text NOT NULL,
    failure_reason text DEFAULT ''::text NOT NULL,
    submitted_at bigint DEFAULT 0 NOT NULL,
    settled_at bigint DEFAULT 0 NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    fee_amount bigint DEFAULT 0 NOT NULL
);

